import{_ as a,o as n,c as s,ag as l}from"./chunks/framework.CmaAMB6e.js";const c=JSON.parse('{"title":"Java 学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"java/learning-path.md","filePath":"java/learning-path.md","lastUpdated":null}'),r={name:"java/learning-path.md"};function i(o,t,e,d,g,p){return n(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="java-学习路径" tabindex="-1">Java 学习路径 <a class="header-anchor" href="#java-学习路径" aria-label="Permalink to &quot;Java 学习路径&quot;">​</a></h1><blockquote><p>Java 专属的概念序列与阶段划分。每个概念自成闭环,不与其他技能绑定。Java 是后端/工程技能,无 UI 层,主线为「语言核心 → 工程化 → Web 后端 → 资深」。</p></blockquote><h2 id="学习策略" tabindex="-1">学习策略 <a class="header-anchor" href="#学习策略" aria-label="Permalink to &quot;学习策略&quot;">​</a></h2><ul><li><strong>概念驱动</strong>:按概念顺序推进,每个概念是一篇完整教程</li><li><strong>前端对照</strong>:每篇末尾有「前端对照」小节,用你已会的 React/Vue/JS 帮助理解</li><li><strong>边学边练</strong>:每篇配练习建议,可用 <code>/practice java &lt;概念&gt;</code> 生成针对性练习</li></ul><h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主题</th><th>概念数</th></tr></thead><tbody><tr><td>1</td><td>基础层</td><td>5</td></tr><tr><td>2</td><td>核心能力层</td><td>5</td></tr><tr><td>3</td><td>工程层</td><td>5</td></tr><tr><td>4</td><td>后端应用层</td><td>5</td></tr><tr><td>5</td><td>资深层</td><td>8</td></tr><tr><td>6</td><td>综合实战</td><td>1</td></tr></tbody></table><hr><h2 id="阶段-1-·-基础层" tabindex="-1">阶段 1 · 基础层 <a class="header-anchor" href="#阶段-1-·-基础层" aria-label="Permalink to &quot;阶段 1 · 基础层&quot;">​</a></h2><p>打地基,建立 Java 的最小可用认知。</p><ul><li><strong>01 Hello World 与项目结构</strong> - JDK 安装、Maven/Gradle 项目骨架、main 入口</li><li><strong>02 语法基础</strong> - 变量、类型、控制流、方法、数组</li><li><strong>03 集合与数据结构</strong> - List / Set / Map 及常用操作</li><li><strong>04 异常处理</strong> - try-catch / finally / 自定义异常 / try-with-resources</li><li><strong>05 OOP 基础</strong> - 类、对象、继承、接口、封装</li></ul><h2 id="阶段-2-·-核心能力层" tabindex="-1">阶段 2 · 核心能力层 <a class="header-anchor" href="#阶段-2-·-核心能力层" aria-label="Permalink to &quot;阶段 2 · 核心能力层&quot;">​</a></h2><p>掌握 Java 语言核心特性。</p><ul><li><strong>06 OOP 深入</strong> - 抽象类、多态、内部类、枚举、组合优于继承</li><li><strong>07 泛型与类型系统</strong> - 泛型类/方法、通配符、类型擦除</li><li><strong>08 Lambda 与函数式接口</strong> - lambda 表达式、方法引用、常用函数式接口</li><li><strong>09 Stream 流式编程</strong> - 惰性求值、map/filter/reduce、并行流</li><li><strong>10 IO 与文件操作</strong> - 字节流/字符流、NIO、读写文件</li></ul><h2 id="阶段-3-·-工程层" tabindex="-1">阶段 3 · 工程层 <a class="header-anchor" href="#阶段-3-·-工程层" aria-label="Permalink to &quot;阶段 3 · 工程层&quot;">​</a></h2><p>进入工程化能力。</p><ul><li><strong>11 构建工具与依赖管理</strong> - Maven / Gradle、坐标、生命周期</li><li><strong>12 单元测试</strong> - JUnit 5、Mockito、断言、覆盖率</li><li><strong>13 网络请求与序列化</strong> - HttpClient、JSON 解析（Jackson/Gson）</li><li><strong>14 数据库访问</strong> - JDBC、连接池（HikariCP）、SQL 基础</li><li><strong>15 并发编程基础</strong> - 线程、Executor、锁、volatile</li></ul><h2 id="阶段-4-·-后端应用层" tabindex="-1">阶段 4 · 后端应用层 <a class="header-anchor" href="#阶段-4-·-后端应用层" aria-label="Permalink to &quot;阶段 4 · 后端应用层&quot;">​</a></h2><p>进入 Java 的主战场:Spring Boot Web 后端。</p><ul><li><strong>16 Spring Boot 入门</strong> - 依赖注入、IoC 容器、自动配置</li><li><strong>17 REST API 开发</strong> - Controller、参数绑定、校验、统一错误处理</li><li><strong>18 Spring Data JPA</strong> - 实体映射、Repository、事务管理</li><li><strong>19 Spring Security 与认证</strong> - 登录鉴权、JWT、角色权限</li><li><strong>20 缓存与任务调度</strong> - Redis 缓存、定时任务、异步任务</li></ul><h2 id="阶段-5-·-资深层" tabindex="-1">阶段 5 · 资深层 <a class="header-anchor" href="#阶段-5-·-资深层" aria-label="Permalink to &quot;阶段 5 · 资深层&quot;">​</a></h2><p>进阶到资深/专家水平:JVM、并发深入、性能、架构、微服务、安全、部署。</p><ul><li><strong>21 JVM 内存与垃圾回收</strong> - 内存模型、GC 算法、调优参数</li><li><strong>22 并发深入</strong> - 并发容器、原子类、CompletableFuture、线程池调优</li><li><strong>23 性能分析与调优</strong> - JFR、Arthas、Profiler、慢接口定位</li><li><strong>24 设计模式与架构</strong> - 常用设计模式、分层架构、DDD 入门</li><li><strong>25 微服务基础</strong> - 服务拆分、注册中心、网关、Feign 调用</li><li><strong>26 测试进阶</strong> - 集成测试、Testcontainers、契约测试</li><li><strong>27 部署与 CI/CD</strong> - Docker 化、K8s 基础、GitLab/GitHub CI</li><li><strong>28 安全加固</strong> - 加密、防注入、OWASP Top 10、密钥管理</li></ul><h2 id="阶段-6-·-综合实战" tabindex="-1">阶段 6 · 综合实战 <a class="header-anchor" href="#阶段-6-·-综合实战" aria-label="Permalink to &quot;阶段 6 · 综合实战&quot;">​</a></h2><ul><li><strong>29 综合实战项目</strong> - 串联全部概念,做一个完整后端项目</li></ul><hr><h2 id="概念依赖关系" tabindex="-1">概念依赖关系 <a class="header-anchor" href="#概念依赖关系" aria-label="Permalink to &quot;概念依赖关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 -&gt; 02 -&gt; 03 -&gt; 04 -&gt; 05          (基础层串行)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        06 -&gt; 07 -&gt; 08 -&gt; 09 -&gt; 10   (核心能力层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        11 -&gt; 12 -&gt; 13 -&gt; 14 -&gt; 15   (工程层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        16 -&gt; 17 -&gt; 18 -&gt; 19 -&gt; 20   (后端应用层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        21 -&gt; 22 -&gt; ... -&gt; 28        (资深层,进阶)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>              29                     (实战,依赖前面全部)</span></span></code></pre></div><h2 id="进度跟踪" tabindex="-1">进度跟踪 <a class="header-anchor" href="#进度跟踪" aria-label="Permalink to &quot;进度跟踪&quot;">​</a></h2><p>每完成一个概念,在 <code>progress.md</code> 更新状态:⬜ 未开始 / 🔄 学习中 / ✅ 已掌握。</p>`,29)])])}const u=a(r,[["render",i]]);export{c as __pageData,u as default};
